using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "IndigoRiteCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/IndigoRiteCustomDescription", order = 0)]
public class IndigoRiteCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		IndigoRiteAction obj = battleAction as IndigoRiteAction;
		string actionDescription = obj.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		string actionDescription2 = obj.IndigoRiteEffectAction.GetActionDescription(EffectsValues.NO_VALUE);
		return actionDescription + "\n" + actionDescription2 + "\n" + Smart.Format(GetRawLocalizedDescription(battleAction), 1);
	}
}
